-- 2.1 USERS TABLE
CREATE TABLE IF NOT EXISTS public.users (
    id SERIAL PRIMARY KEY,
    name TEXT NOT NULL,
    email TEXT UNIQUE NOT NULL,
    mobile TEXT,
    password_hash TEXT NOT NULL,
    role TEXT DEFAULT 'user',
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

-- 2.2 CONVOCATION STUDENTS TABLE
CREATE TABLE IF NOT EXISTS public.convocation_students (
    id SERIAL PRIMARY KEY,
    university TEXT,
    hall_ticket_no TEXT UNIQUE NOT NULL,
    candidate_name TEXT,
    father_name TEXT,
    dob DATE,
    gender TEXT,
    category TEXT,
    aadhaar_no TEXT,
    mode_of_study TEXT,
    degree TEXT,
    faculty TEXT,
    course_group TEXT,
    subject TEXT,
    specialization TEXT,
    research_title TEXT,
    research_date DATE,
    
    part1_class TEXT,
    part1_month TEXT,
    part1_year TEXT,
    part1_grade TEXT,
    
    part2_class TEXT,
    part2_month TEXT,
    part2_year TEXT,
    part2_grade TEXT,
    
    part3_class TEXT,
    part3_month TEXT,
    part3_year TEXT,
    part3_grade TEXT,
    
    medium TEXT,
    student_photo TEXT,
    student_photo_blob BYTEA,
    
    payment_category TEXT,
    payment_mode TEXT,
    dd_challan_no TEXT,
    dd_challan_date DATE,
    dd_challan_certificate TEXT,
    dd_challan_certificate_blob BYTEA,
    
    issued_date DATE,
    bank_name TEXT,
    ifsc_code TEXT,
    convocation_fee NUMERIC,
    convocation_issued_in TEXT,
    
    second_language TEXT,
    elective_subjects TEXT,
    academic_year TEXT,
    remarks TEXT,
    
    submitted_by INTEGER REFERENCES public.users(id) ON DELETE SET NULL,
    created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP WITH TIME ZONE,
    manual_serial_no TEXT,
    branch_name TEXT,
    part_ii TEXT,
    part_iii TEXT
);

